SELECT review_id AS reviewId, meetup_id AS meetupId, member_id AS memberId, content, rating, likes_count AS likesCount, views_count AS viewsCount, is_public AS isPublic, CASE WHEN delete_yn = 'Y' THEN 1 ELSE 0 END AS deleteYn, TO_CHAR(created_at, 'YYYY-MM-DD HH24:MI:SS') AS createdAt, TO_CHAR(updated_at, 'YYYY-MM-DD HH24:MI:SS') AS updatedAt FROM REVIEWS WHERE delete_yn = 'N'
AND member_id = #{memberId}
ORDER BY review_id DESC

SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY review_id DESC) AS rn, r.* FROM REVIEWS r WHERE delete_yn = 'N'
AND content LIKE '%' || #{keyword} || '%'
AND member_id = #{memberId}
) WHERE rn BETWEEN #{paging.pstartno} AND #{endRow}

